import{_ as r,o as d,c as o,a0 as e}from"./chunks/framework.UHt1LHnn.js";const C=JSON.parse('{"title":"📖 들어가며","description":"","frontmatter":{},"headers":[],"relativePath":"prologue.md","filePath":"prologue.md"}'),a={name:"prologue.md"};function n(l,t,s,i,g,u){return d(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="📖-들어가며" tabindex="-1">📖 들어가며 <a class="header-anchor" href="#📖-들어가며" aria-label="Permalink to &quot;📖 들어가며&quot;">​</a></h1><blockquote><p>비개발자를 위한 AI 업무 자동화 실전 가이드 — Prologue</p></blockquote><h2 id="✏️-이-백서를-쓰게-된-이유" tabindex="-1">✏️ 이 백서를 쓰게 된 이유 <a class="header-anchor" href="#✏️-이-백서를-쓰게-된-이유" aria-label="Permalink to &quot;✏️ 이 백서를 쓰게 된 이유&quot;">​</a></h2><p>기획자는 늘 경계에 서 있습니다.<br> 개발팀과 사업팀 사이, 요구사항과 구현 가능성 사이, 그리고 빠르게 변하는 기술과 현실적인 업무 속도 사이에서.</p><p>저는 클라우드 서비스 기획자입니다. 기획 업무를 기반으로 하되, 개발 언어를 읽고 분석할 수 있으며, API와 SDK를 직접 검증하고, 다양한 데이터베이스를 다룰 수 있습니다. 기획 검증 단계에서 개발 관점의 사고를 함께 적용해왔습니다.</p><p>그러던 중 <strong>Claude Code</strong>를 만났고, 제 업무 방식이 달라지기 시작했습니다.<br> 단순히 &quot;AI에게 질문하는 것&quot;을 넘어서, <strong>MCP 연동, 자동화 툴 구축, 문서 자동 생성</strong>까지 — 기획자의 손으로 직접 만들어낼 수 있다는 걸 경험했습니다.</p><p>이 백서는 그 경험의 기록입니다. 화려한 기술 스택을 설명하는 문서가 아니라, **&quot;기획자가 Claude Code를 어떻게 실제 업무에 녹여냈는가&quot;**에 대한 실전 가이드입니다.</p><h2 id="👤-이-백서를-쓴-사람" tabindex="-1">👤 이 백서를 쓴 사람 <a class="header-anchor" href="#👤-이-백서를-쓴-사람" aria-label="Permalink to &quot;👤 이 백서를 쓴 사람&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td><strong>역할</strong></td><td>클라우드 서비스 기획자 (Kakao Enterprise)</td></tr><tr><td><strong>기술 배경</strong></td><td>개발 경험 보유 / 코드 분석 가능 / 다양한 DB 운용 경험</td></tr><tr><td><strong>기획 역량</strong></td><td>API · SDK 기획 검증, 서비스 스펙 설계, 사용자 가이드 작성</td></tr><tr><td><strong>AI 활용 수준</strong></td><td>Claude Code CLI + MCP 다중 연동 + 자동화 툴 직접 구축</td></tr><tr><td><strong>주요 연동 MCP</strong></td><td>Confluence, Jira, Figma, GitHub, Kakao Cloud Docs</td></tr></tbody></table><h2 id="🤔-왜-claude-code인가" tabindex="-1">🤔 왜 Claude Code인가 <a class="header-anchor" href="#🤔-왜-claude-code인가" aria-label="Permalink to &quot;🤔 왜 Claude Code인가&quot;">​</a></h2><p>기획자에게 필요한 것은 단순한 챗봇이 아닙니다. 맥락을 이해하고, 시스템과 연동되며, 반복 작업을 자동화하고, 결과물을 직접 만들어내는 도구가 필요합니다.</p><div class="tip custom-block"><p class="custom-block-title">✅ Claude Code가 충족한 조건</p><ul><li><strong>MCP(Model Context Protocol)</strong> 를 통해 Confluence, Jira, Figma 등 업무 도구와 직접 연결됩니다.</li><li>터미널 기반 CLI로 동작하며, 코드·문서·API를 하나의 흐름에서 처리할 수 있습니다.</li><li>프로젝트 설정 파일(<code>CLAUDE.md</code>)과 커스텀 명령어로 팀 맞춤 어시스턴트를 만들 수 있습니다.</li><li>개발 지식이 있는 기획자라면, 단순 자동화를 넘어 <strong>직접 툴을 설계하고 구축</strong>하는 수준까지 활용할 수 있습니다.</li></ul></div><h2 id="📚-이-백서의-구성" tabindex="-1">📚 이 백서의 구성 <a class="header-anchor" href="#📚-이-백서의-구성" aria-label="Permalink to &quot;📚 이 백서의 구성&quot;">​</a></h2><p>이 백서는 총 9개의 챕터로 구성되며, 각 챕터는 독립적으로 참고할 수 있습니다.</p><table tabindex="0"><thead><tr><th>챕터</th><th>주제</th><th>핵심 내용</th></tr></thead><tbody><tr><td><strong>CH.0</strong></td><td>기획자에게 Claude Code가 필요한 이유</td><td>도입 배경, 기대 효과</td></tr><tr><td><strong>CH.1</strong></td><td>환경 구축</td><td>설치, MCP 연동 세팅</td></tr><tr><td><strong>CH.2</strong></td><td>반복 업무의 종말</td><td>자동화 대상 발굴, Before/After</td></tr><tr><td><strong>CH.3</strong></td><td>MCP Confluence 연동</td><td>회의록·기획서·스펙 문서 자동화</td></tr><tr><td><strong>CH.4</strong></td><td>MCP Jira 연동</td><td>티켓 생성·관리 자동화</td></tr><tr><td><strong>CH.5</strong></td><td>MCP Figma 연동</td><td>기획 화면 시안 제작</td></tr><tr><td><strong>CH.6</strong></td><td>카카오클라우드 사용자 가이드 작성</td><td>KC-docs 기반 초안 자동 생성</td></tr><tr><td><strong>CH.7</strong></td><td>API 자동화 테스트 툴 구축</td><td>Swagger JSON → 자동화 테스트 툴</td></tr><tr><td><strong>CH.8</strong></td><td>경쟁사·레퍼런스 분석 자동화</td><td>리서치 → 보고서 자동 생성</td></tr><tr><td><strong>CH.9</strong></td><td>나만의 기획 어시스턴트 만들기</td><td>CLAUDE.md + 커스텀 명령어 총정리</td></tr></tbody></table><h2 id="🙋-이-백서가-도움이-될-분" tabindex="-1">🙋 이 백서가 도움이 될 분 <a class="header-anchor" href="#🙋-이-백서가-도움이-될-분" aria-label="Permalink to &quot;🙋 이 백서가 도움이 될 분&quot;">​</a></h2><ul><li>📌 Claude Code를 업무에 적용하고 싶은 <strong>IT 기획자 / PM</strong></li><li>📌 개발 지식은 있지만 AI 툴 활용을 막 시작하는 <strong>테크 기획자</strong></li><li>📌 Confluence, Jira, Figma를 매일 쓰면서 <strong>반복 작업에 지친 실무자</strong></li><li>📌 AI 기반 업무 자동화를 팀에 도입하고 싶은 <strong>리드/매니저</strong></li></ul><blockquote><p>💡 이 백서는 완성된 정답이 아니라, <strong>현재 진행 중인 실험의 기록</strong>입니다.<br> 각 챕터는 실제 업무에서 사용한 방법과 결과를 바탕으로 작성되었으며, 함께 발전시켜 나갈 수 있습니다.</p></blockquote>',18)])])}const h=r(a,[["render",n]]);export{C as __pageData,h as default};
